from pathlib import Path
import os, sys
ROOT = Path(__file__).resolve().parent.parent
os.chdir(ROOT)
sys.path.insert(0, str(ROOT))
EXERCISES = {'1': 'from pathlib import Path\nimport numpy as np\n\npath = Path("results/hydration/CM_Ca_r1_hydrated/samples.npz")\nwith np.load(path, allow_pickle=False) as archive:\n    d = archive["distances_nm"]\n    time = archive["time_ps"]\n\nmask = d < 0.35\nprint("全部距离:", d.shape)\nprint("第一帧:", d[0].shape)\nprint("第一个水氧的时间序列:", d[:, 0].shape)\nprint("每帧 CN:", mask.sum(axis=1).shape)\nprint("每个水氧入壳帧数:", mask.sum(axis=0).shape)\nprint("时间端点:", time[0], time[-1])\nprint("第一帧 CN:", int(mask[0].sum()))\nassert d.shape == (2000, 877)\nassert mask.sum(axis=1).shape == (2000,)\nassert mask.sum(axis=0).shape == (877,)', '2': 'import numpy as np\n\nwith np.load("results/hydration/CM_Ca_r1_hydrated/samples.npz",\n             allow_pickle=False) as archive:\n    d = archive["distances_nm"]\n\ninside = d < 0.35                 # 每个距离变成 True 或 False\ncn = inside.sum(axis=1)            # True 当作 1：每帧数水氧\nmean_cn = cn.mean()                # 对 2000 个逐帧计数取平均\nvalues, counts = np.unique(cn, return_counts=True)\nprint(values.tolist(), counts.tolist())\nprint(f"mean CN = {mean_cn:.4f}")\nmanual = (7 * 11 + 8 * 1875 + 9 * 114) / 2000\nassert counts.sum() == len(d) == 2000\nassert np.isclose(mean_cn, manual)\nassert np.isclose(mean_cn, 8.0515)', '3': 'import numpy as np\n\nwith np.load("results/amide/CM_Ca_r3_contact/samples.npz",\n             allow_pickle=False) as archive:\n    distance = archive["amide_distance_nm"]\n\nassert distance.ndim == 1 and np.all(np.isfinite(distance))\ncontact = distance < 0.35\nhits = int(contact.sum())\nfraction = float(contact.mean())\nprint(f"{hits}/{len(distance)} = {100 * fraction:.2f}%")\nassert hits == 297 and len(distance) == 2000\nassert np.isclose(fraction, 0.1485)', '4': 'from pathlib import Path\nimport csv\nimport json\nimport numpy as np\n\ndef simple_rdf(d, volume, edges):\n    # 教学版逐帧循环；原 analyze.py 按块计数，以节省临时内存。\n    d = np.asarray(d, dtype=float)\n    volume = np.asarray(volume, dtype=float)\n    edges = np.asarray(edges, dtype=float)\n    if d.ndim != 2 or min(d.shape) == 0:\n        raise ValueError("d 必须是非空的 帧×水氧 二维数组")\n    if volume.shape != (len(d),):\n        raise ValueError("每帧必须有一个体积")\n    if not np.all(np.isfinite(d)) or np.any(d < 0):\n        raise ValueError("距离必须有限且非负")\n    if not np.all(np.isfinite(volume)) or np.any(volume <= 0):\n        raise ValueError("体积必须有限且为正")\n    if (edges.ndim != 1 or len(edges) < 2\n            or not np.all(np.isfinite(edges))\n            or edges[0] < 0 or np.any(np.diff(edges) <= 0)):\n        raise ValueError("bin 边界必须有限、非负、严格递增")\n    shell_volume = 4 * np.pi / 3 * np.diff(edges ** 3)\n    g_sum = np.zeros(len(edges) - 1)\n    count_sum = np.zeros(len(edges) - 1)\n    for row, box_volume in zip(d, volume):\n        # np.histogram 最后一格含右端点；显式排除它以匹配项目定义。\n        selected = row[(row >= edges[0]) & (row < edges[-1])]\n        counts, _ = np.histogram(selected, bins=edges)\n        density = d.shape[1] / box_volume\n        g_sum += counts / (density * shell_volume)\n        count_sum += counts\n    return g_sum / len(d), np.cumsum(count_sum) / len(d)\n\n# 手算例子：2 帧、每帧 2 个水氧，但体积不同。\ntoy = np.array([[0.10, 0.30], [0.10, 0.15]])\ntoy_edges = np.array([0.0, 0.2, 0.4])\ng, cn = simple_rdf(toy, np.array([1.0, 2.0]), toy_edges)\nshells = 4 * np.pi / 3 * np.diff(toy_edges ** 3)\nassert np.allclose(g * shells, [1.25, 0.25])\nassert np.allclose(cn, [1.5, 2.0])\nprint("两帧手算自检通过")\n\ncase = Path("results/hydration/CM_Ca_r1_hydrated")\nmeta = json.loads((case / "metadata.json").read_text(encoding="utf-8"))\nedges = np.arange(451, dtype=float) * 0.002  # 0 至 0.9 nm\nassert meta["min_box_length_nm"] > 2 * edges[-1]\nwith np.load(case / "samples.npz", allow_pickle=False) as archive:\n    g, cumulative_cn = simple_rdf(archive["distances_nm"],\n                                  archive["volume_nm3"], edges)\nr = (edges[:-1] + edges[1:]) / 2\nindices = np.flatnonzero((r >= 0.20) & (r <= 0.32))\npeak = r[indices[np.argmax(g[indices])]]\nprint(f"Ca 第一峰 = {peak:.3f} nm")\n\nwith open("results/analysis/rdf_curves.csv", encoding="utf-8", newline="") as f:\n    saved = [row for row in csv.DictReader(f)\n             if row["campaign"] == "hydration" and row["case"] == case.name]\nassert len(saved) == len(g) == 450\nassert np.allclose(g, [float(row["g_M_waterO"]) for row in saved])\nassert np.allclose(cumulative_cn,\n                   [float(row["mean_CN_through_bin_upper"]) for row in saved])\nprint("450 个 RDF bin 与项目结果一致")', '5': 'from pathlib import Path\nimport numpy as np\n\nfractions = []\nfor replica in (1, 2, 3):\n    path = Path(f"results/amide/CM_Ca_r{replica}_contact/samples.npz")\n    with np.load(path, allow_pickle=False) as archive:\n        distance = archive["amide_distance_nm"]\n    assert distance.shape == (2000,) and np.all(np.isfinite(distance))\n    fractions.append(float(np.mean(distance < 0.35)))\n\npercent = np.array(fractions) * 100\nprint("replica 接触百分比:", [f"{x:.2f}" for x in percent])\nprint(f"mean = {percent.mean():.6f}%")\nprint(f"sample SD = {percent.std(ddof=1):.6f} 个百分点")\nassert np.allclose(fractions, [0.999, 0.842, 0.1485])\nassert np.isclose(percent.std(ddof=1), 45.257439535763986)', '6': 'from pathlib import Path\nimport numpy as np\n\ncutoffs = np.array([0.33, 0.35, 0.37])\nrows = []\nfor replica in (1, 2, 3):\n    path = Path(f"results/hydration/CM_Ca_r{replica}_hydrated/samples.npz")\n    with np.load(path, allow_pickle=False) as archive:\n        d = archive["distances_nm"]\n    assert d.ndim == 2 and d.shape[0] == 2000\n    assert np.all(np.isfinite(d)) and np.all(d >= 0)\n    rows.append([(d < cutoff).sum(axis=1).mean() for cutoff in cutoffs])\ntable = np.array(rows)\nassert table.shape == (3, 3)\nassert np.all(np.diff(table, axis=1) >= 0)\nfor replica, row in enumerate(table, start=1):\n    print(f"r{replica}:", " ".join(f"{x:.4f}" for x in row))\nprint("mean:", " ".join(f"{x:.6f}" for x in table.mean(axis=0)))\nprint("SD:", " ".join(f"{x:.6f}" for x in table.std(axis=0, ddof=1)))\nassert np.allclose(table, [[8.036, 8.0515, 8.073],\n                           [8.0235, 8.0335, 8.0635],\n                           [8.028, 8.041, 8.071]])'}
choice = sys.argv[1] if len(sys.argv) > 1 else "1"
if choice not in (*EXERCISES, "all"):
    raise SystemExit("Choose 1..6 or all")
for number in (EXERCISES if choice == "all" else [choice]):
    print("Exercise", number)
    exec(compile(EXERCISES[number], "exercise_" + number, "exec"), {"__name__": "__main__"})
